<div class="page-title clearfix"><h1>Campaign Delivery Log</h1><a class="btn btn-default float-end" href="<?php echo site_url('email_marketing'); ?>">Campaigns</a></div><div class="card"><table class="table"><thead><tr><th>Recipient</th><th>Name</th><th>Mode</th><th>Status</th><th>Queued</th><th>Sent</th><th>Error</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php echo esc($r->email); ?></td><td><?php echo esc($r->recipient_name); ?></td><td><?php echo ((int)($r->is_test??0)===1)?'TEST EMAIL':'LIVE'; ?></td><td><?php echo esc($r->status); ?></td><td><?php echo esc($r->queued_at); ?></td><td><?php echo esc($r->sent_at??''); ?></td><td><?php echo esc($r->error_details??''); ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="7">No delivery records.</td></tr><?php endif; ?></tbody></table></div>
